return [{
  json: {
    sheetId: 'REPLACE_WITH_GOOGLE_SHEET_ID',
    sheetName: 'Invoices',
    openAiModel: 'gpt-4.1-mini',
    senderName: 'Accounts Receivable',
    signature: 'Best,\nAccounts Receivable',
    defaultPaymentInstructions: 'Please reply if you need the invoice resent or have a question about payment.',
    lookbackDays: 90,
    recentConversationHours: 72
  }
}];

const rows = $input.all();
const now = new Date();
const DAY = 86400000;
const thresholds = [7, 14, 21, 28];

function truthy(v) {
  return ['true','yes','1','y'].includes(String(v ?? '').trim().toLowerCase()) || v === true;
}
function parseDate(v) {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d;
}

const out = [];
for (const item of rows) {
  const r = { ...item.json };
  const status = String(r['Status'] ?? '').trim().toLowerCase();
  const collectionStatus = String(r['Collection Status'] ?? '').trim().toLowerCase();
  if (['paid','closed','void','cancelled','canceled'].includes(status)) continue;
  if (truthy(r['Manual Hold'])) continue;
  if (collectionStatus === 'human review') continue;
  if (!r['Invoice ID'] || !r['Email']) continue;

  let due = parseDate(r['Due Date']);
  if (!due) {
    const sent = parseDate(r['Date Sent']);
    if (!sent) continue;
    due = new Date(sent.getTime() + 30 * DAY);
  }

  const daysOverdue = Math.floor((now - due) / DAY);
  if (daysOverdue < 7) continue;

  const lastStage = Math.max(0, Number.parseInt(r['Last Reminder Stage'] || '0', 10) || 0);
  if (lastStage >= 4) continue;

  const nextStage = lastStage + 1;
  const requiredDays = thresholds[nextStage - 1];
  if (daysOverdue < requiredDays) continue;

  const nextFollow = parseDate(r['Next Follow-Up At']);
  if (nextFollow && now < nextFollow) continue;

  const subjectByStage = {
    1: `Quick reminder: Invoice ${r['Invoice ID']}`,
    2: `Follow-up: Invoice ${r['Invoice ID']}`,
    3: `Action requested: Invoice ${r['Invoice ID']}`,
    4: `Final notice: Invoice ${r['Invoice ID']}`,
  };

  out.push({
    json: {
      ...r,
      _due_date_iso: due.toISOString(),
      _days_overdue: daysOverdue,
      _next_stage: nextStage,
      _required_days: requiredDays,
      _expected_subject: subjectByStage[nextStage],
      _reminder_key: `${r['Invoice ID']}:S${nextStage}`,
      _gmail_query: `(from:${r['Email']} OR to:${r['Email']}) newer_than:${$('Initialize Configurations').first().json.lookbackDays}d`
    }
  });
}
return out;

const invoice = $('Loop Through Invoices').item.json;
const messages = $input.all().map(i => i.json || {}).filter(x => Object.keys(x).length);
const cfg = $('Initialize Configurations').first().json;
const now = Date.now();
const cutoff = now - Number(cfg.recentConversationHours || 72) * 3600000;

function first(obj, keys) {
  for (const k of keys) if (obj?.[k] !== undefined && obj?.[k] !== null) return obj[k];
  return '';
}
function timeOf(m) {
  const raw = first(m, ['date','Date','internalDate','receivedAt','timestamp']);
  if (!raw) return null;
  const n = Number(raw);
  if (Number.isFinite(n) && n > 1+1234567890) return n;
  if (Number.isFinite(n) && n > 1+1234567890) return n * 1000;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d.getTime();
}

const compact = messages.slice(0, 20).map(m => ({
  id: first(m, ['id','messageId']),
  threadId: first(m, ['threadId']),
  from: first(m, ['From','from']),
  to: first(m, ['To','to']),
  subject: first(m, ['Subject','subject']),
  date: first(m, ['Date','date','receivedAt']),
  snippet: String(first(m, ['snippet','textPlain','text','body']) || '').slice(0, 900)
}));

const alreadySentStage = compact.some(m => String(m.subject || '').trim() === String(invoice._expected_subject || '').trim());
const recentConversation = compact.some(m => {
  const t = timeOf(m);
  return t !== null && t >= cutoff;
});
const newest = compact.map(m => ({m, t: timeOf(m)})).filter(x => x.t).sort((a,b)=>b.t-a.t)[0];

return [{json:{
  ...invoice,
  _already_sent_stage: alreadySentStage,
  _recent_conversation: recentConversation,
  _newest_message_at: newest ? new Date(newest.t).toISOString() : '',
  _last_email_thread_id: newest?.m?.threadId || '',
  _email_history: compact
}}];

const x = $input.first().json;
const now = new Date();
const next = new Date(now.getTime() + 7 * 86400000);
return [{json:{
  ...x,
  'Last Reminder Stage': x._next_stage,
  'Last Reminder At': x['Last Reminder At'] || now.toISOString(),
  'Next Follow-Up At': x._next_stage >= 4 ? '' : next.toISOString(),
  'Collection Status': x._next_stage >= 4 ? 'Human Review' : 'Active',
  'Last AI Decision': 'RECONCILED_FROM_GMAIL',
  'Last AI Reason': `Exact stage subject already exists in Gmail: ${x._expected_subject}`,
  'Last Email Thread ID': x._last_email_thread_id || x['Last Email Thread ID'] || '',
  'Last Reminder Key': x._reminder_key
}}];

const x = $input.first().json;
const hours = Number($('Initialize Configurations').first().json.recentConversationHours || 72);
const base = x._newest_message_at ? new Date(x._newest_message_at) : new Date();
const next = new Date(base.getTime() + hours * 3600000);
return [{json:{
  ...x,
  'Next Follow-Up At': next.toISOString(),
  'Collection Status': 'Deferred - Recent Conversation',
  'Last AI Decision': 'DEFER_RULE',
  'Last AI Reason': `Recent client email activity detected within ${hours} hours`,
  'Last Email Thread ID': x._last_email_thread_id || x['Last Email Thread ID'] || ''
}}];

