const base = $('Construct Email Context').item.json;
const raw = $input.first().json;

function stringsDeep(v, out = []) {
  if (typeof v === 'string') out.push(v);
  else if (Array.isArray(v)) for (const x of v) stringsDeep(x, out);
  else if (v && typeof v === 'object') for (const x of Object.values(v)) stringsDeep(x, out);
  return out;
}
function tryParse(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
  try { return JSON.parse(t); } catch {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a,b+1)); } catch {} }
  return null;
}

let parsed = null;
for (const s of stringsDeep(raw)) {
  const p = tryParse(s);
  if (p && typeof p === 'object' && p.decision) { parsed = p; break; }
}
if (!parsed) {
  parsed = {decision:'HUMAN', reason:'AI output could not be parsed safely', confidence:0, reference_sentence:''};
}
let decision = String(parsed.decision || 'HUMAN').toUpperCase();
if (!['SEND','DEFER','HUMAN'].includes(decision)) decision = 'HUMAN';
const confidence = Math.max(0, Math.min(1, Number(parsed.confidence || 0)));
if (decision === 'SEND' && confidence < 0.65) decision = 'HUMAN';

return [{json:{
  ...base,
  _ai_decision: decision,
  _ai_reason: String(parsed.reason || ''),
  _ai_confidence: confidence,
  _reference_sentence: confidence >= 0.80 ? String(parsed.reference_sentence || '').trim() : ''
}}];

const x = $input.first().json;
const cfg = $('Initialize Configurations').first().json;
const stage = Number(x._next_stage);
const name = String(x['Client Name'] || 'there').trim();
const invoiceId = x['Invoice ID'];
const due = new Date(x._due_date_iso).toLocaleDateString('en-US', {year:'numeric',month:'short',day:'numeric'});
const amountRaw = x['Amount'];
const amount = amountRaw !== undefined && amountRaw !== null && String(amountRaw).trim() !== '' ? ` for ${amountRaw}` : '';
const payment = String(x['Payment Link'] || '').trim();
const contextual = String(x._reference_sentence || '').trim();

const intros = {
  1: `Just a quick reminder that invoice ${invoiceId}${amount} was due on ${due}.`,
  2: `I'm following up again on invoice ${invoiceId}${amount}, which was due on ${due}.`,
  3: `Invoice ${invoiceId}${amount} remains outstanding. Please arrange payment or let us know today if there is an issue we need to resolve.`,
  4: `This is the final automated notice for invoice ${invoiceId}${amount}, originally due on ${due}. Please arrange payment or contact us promptly so we can resolve any issue before this is moved to manual review.`
};

let lines = [`Hi ${name},`, '', intros[stage]];
if (contextual) lines.push('', contextual);
if (payment) lines.push('', `Payment link: ${payment}`);
lines.push('', cfg.defaultPaymentInstructions, '', cfg.signature);

return [{json:{
  ...x,
  email_subject: x._expected_subject,
  email_body: lines.filter((v,i,a) => !(v === '' && i > 0 && a[i-1] === '')).join('\n')
}}];

const x = $('Craft Deterministic Email').item.json;
const now = new Date();
const next = new Date(now.getTime() + 7 * 86400000);
return [{json:{
  ...x,
  'Last Reminder Stage': x._next_stage,
  'Last Reminder At': now.toISOString(),
  'Next Follow-Up At': x._next_stage >= 4 ? '' : next.toISOString(),
  'Collection Status': x._next_stage >= 4 ? 'Human Review' : 'Active',
  'Last AI Decision': 'SEND',
  'Last AI Reason': x._ai_reason || '',
  'Last Email Thread ID': x._last_email_thread_id || x['Last Email Thread ID'] || '',
  'Last Reminder Key': x._reminder_key
}}];

const x = $input.first().json;
return [{json:{
  ...x,
  'Collection Status': 'Human Review',
  'Next Follow-Up At': '',
  'Last AI Decision': 'HUMAN',
  'Last AI Reason': x._ai_reason || 'Manual review required',
  'Last Email Thread ID': x._last_email_thread_id || x['Last Email Thread ID'] || ''
}}];

const x = $input.first().json;
const next = new Date(Date.now() + 72 * 3600000);
return [{json:{
  ...x,
  'Collection Status': 'Deferred - AI Context',
  'Next Follow-Up At': next.toISOString(),
  'Last AI Decision': 'DEFER',
  'Last AI Reason': x._ai_reason || 'Email context suggests waiting before follow-up',
  'Last Email Thread ID': x._last_email_thread_id || x['Last Email Thread ID'] || ''
}}];
